CREATE TABLE IF NOT EXISTS "Club" ("id" SERIAL PRIMARY KEY, "name" TEXT NOT NULL, "nameKey" TEXT NOT NULL, "description" TEXT NOT NULL DEFAULT '', "shortName" TEXT NOT NULL DEFAULT '', "city" TEXT NOT NULL DEFAULT '', "status" TEXT NOT NULL DEFAULT 'PENDING', "source" TEXT NOT NULL DEFAULT 'USER', "leagueId" INTEGER REFERENCES "League"("id") ON DELETE SET NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS "Club_nameKey_key" ON "Club"("nameKey");
CREATE UNIQUE INDEX IF NOT EXISTS "Club_leagueId_key" ON "Club"("leagueId");
ALTER TABLE "User" ADD COLUMN IF NOT EXISTS "clubId" INTEGER REFERENCES "Club"("id");
ALTER TABLE "User" ADD COLUMN IF NOT EXISTS "clubChoiceAt" TIMESTAMP(3);
CREATE TABLE IF NOT EXISTS "ClubResponsibility" ("id" SERIAL PRIMARY KEY, "clubId" INTEGER NOT NULL REFERENCES "Club"("id"), "userId" INTEGER NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "status" TEXT NOT NULL DEFAULT 'PENDING', "reason" TEXT NOT NULL, "reviewedBy" INTEGER, "reviewedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS "ClubResponsibility_clubId_userId_key" ON "ClubResponsibility"("clubId","userId");
CREATE INDEX IF NOT EXISTS "ClubResponsibility_status_idx" ON "ClubResponsibility"("status");
